{"description":"Extract which shims were actually called in dumps","command":"python3 -c "
import json, glob, os
from collections import Counter

dumps_dir = '/work/out/packet/dumps'
shim_calls = Counter()
shim_sym_calls = Counter()

for f in sorted(glob.glob(os.path.join(dumps_dir, 'dump_*.json'))):
    with open(f) as fp:
        d = json.load(fp)
    decls = d.get('declarations', {})
    shim_names = {n for n, info in decls.items() if info.get('kind') == 'shim'}

    # Count calls to SHIM targets in the trace
    for entry in d.get('trace', []):
        target = entry.get('target', '')
        if target in shim_names:
            if entry.get('type') == 'symbolic_call':
                shim_sym_calls[target] += 1
            elif entry.get('type') == 'call':
                shim_calls[target] += 1

print('=== SHIMs actually called (as call or symbolic_call) ===')
all_called = set(list(shim_calls.keys()) + list(shim_sym_calls.keys()))
for name in sorted(all_called):
    print(f'  {name}: {shim_calls[name]} call, {shim_sym_calls[name]} symbolic_call')

print()
# Which SHIMs are declared but never called?
declared_shims = set()
for f in sorted(glob.glob(os.path.join(dumps_dir, 'dump_*.json'))):
    with open(f) as fp:
        d = json.load(fp)
    for n, info in d.get('declarations', {}).items():
        if info.get('kind') == 'shim':
            declared_shims.add(n)

never_called = declared_shims - all_called
print('=== SHIMs declared but NEVER called in any dump ===')
for name in sorted(never_called):
    print(f'  {name}')
" 2>&1"}

{"description":"Extract called shims from events","command":"python3 -c "
import json, glob, os
from collections import Counter

dumps_dir = '/work/out/packet/dumps'
shim_sym_calls = Counter()
shim_calls = Counter()
all_shim_names = set()

for f in sorted(glob.glob(os.path.join(dumps_dir, 'dump_*.json'))):
    with open(f) as fp:
        d = json.load(fp)
    shim_names = {n for n, info in d.get('declarations', {}).items() if info.get('kind') == 'shim'}
    all_shim_names.update(shim_names)

    for entry in d.get('events', []):
        target = entry.get('target', '')
        if target in shim_names:
            if entry.get('type') == 'symbolic_call':
                shim_sym_calls[target] += 1
            elif entry.get('type') == 'call':
                shim_calls[target] += 1

print('=== SHIMs called (as call or symbolic_call) ===')
all_called = set(list(shim_calls.keys()) + list(shim_sym_calls.keys()))
for name in sorted(all_called):
    print(f'  {name}: {shim_calls[name]} call, {shim_sym_calls[name]} symbolic_call')

print()
never_called = all_shim_names - all_called
print(f'=== SHIMs declared but NEVER called: {len(never_called)} ===')
for name in sorted(never_called):
    print(f'  {name}')
print(f'=== SHIMs actually called: {len(all_called)} ===')
" 2>&1"}

