import json, os

packet_dir = '/work/out/packet'
errors = []
for f in ['packet.json', 'assumptions.json', 'assumption_manifest.json']:
    path = os.path.join(packet_dir, f)
    try:
        with open(path) as fp:
            json.load(fp)
        print(f'  {f}: valid JSON')
